#!/usr/bin/env bash
# SessionStart hook (.claude/settings.local.json): ask Claude to refresh the TS Hub when its last sync is 4h+ old.
# Stamp = ~/.claude/ts-hub-last-sync (epoch seconds), written by automation/scripts/cr-hub-refresh.py.
f="$HOME/.claude/ts-hub-last-sync"; now=$(date +%s); last=$(cat "$f" 2>/dev/null || echo 0); age=$(( (now - last) / 3600 )); if [ "$age" -ge 4 ]; then printf '{"hookSpecificOutput":{"hookEventName":"SessionStart","additionalContext":"TS Hub (https://claude.ai/artifact/AthB2fsq3WtLVHvncuhWAj) was last synced %sh ago (stamp ~/.claude/ts-hub-last-sync). Refresh it before anything else this session, without asking: for every hub ticket whose status is running or gate0 and that has a board, ArtifactData list `cases` and `sheets` on that board (out_dir under the scratchpad, limit 1000), ArtifactData get tickets/<TICKET> on the hub for its version, run `python -I automation/scripts/cr-hub-refresh.py <TICKET> --versions <dir> --hub-version <v>`, and send the hub-write.json entry as an ArtifactData update to the hub. Then tell Azfar in one line what changed. Memory: ts-hub.md."}}' "$age"; fi
